const results = new Map();
let nextOrderId = 1;

function createOrder(payload, idempotencyKey) {
  if (!idempotencyKey) throw new Error("key required");
  const fingerprint = JSON.stringify(payload);
  const previous = results.get(idempotencyKey);

  if (previous) {
    if (previous.fingerprint !== fingerprint) {
      throw new Error("key reused for different payload");
    }
    return { ...previous.result, replay: true };
  }

  const result = { orderId: `order-${nextOrderId++}`, status: "accepted" };
  results.set(idempotencyKey, { fingerprint, result });
  return { ...result, replay: false };
}

